sion_id":"5558253d-e704-5e89-b7dd-7eedee391e58","subsystem_id":"a842ebb8-c61c-5f2a-ba6c-163e9eb91000","rationale":"按源分配表及用户确认名称导入"},{"project_id":"10d4c8a0-ff3a-56c3-abf6-18dc3b531e62","function_id":"29fe01ea-f727-58cf-a326-b75294ba4dbb","allocation_revision_id":"8f5920ad-a909-5c53-a8d1-b284c291d154","design_version_id":"5558253d-e704-5e89-b7dd-7eedee391e58","subsystem_id":"3ff3cd05-81f7-5583-aa8b-c755a3ae4e5a","rationale":"按源分配表及用户确认名称导入"},{"project_id":"10d4c8a0-ff3a-56c3-abf6-18dc3b531e62","function_id":"29fe01ea-f727-58cf-a326-b75294ba4dbb","allocation_revision_id":"d2a96639-73f6-5bd2-9b01-371654afeec3","design_version_id":"5558253d-e704-5e89-b7dd-7eedee391e58","subsystem_id":"2b090d33-189a-5df0-94b7-80bbfd00b35f","rationale":"按源分配表及用户确认名称导入"},{"project_id":"10d4c8a0-ff3a-56c3-abf6-18dc3b531e62","function_id":"29fe01ea-f727-58cf-a326-b75294ba4dbb","allocation_revision_id":"23ecf62a-2085-5ae5-b443-5d43598b9533","design_version_id":"5558253d-e704-5e89-b7dd-7eedee391e58","subsystem_id":"2b090d33-189a-5df0-94b7-80bbfd00b35f","rationale":"按源分配表及用户确认名称导入"},{"project_id":"10d4c8a0-ff3a-56c3-abf6-18dc3b531e62","function_id":"29fe01ea-f727-58cf-a326-b75294ba4dbb","allocation_revision_id":"cc5c4d1f-f597-5c8d-bf4e-41ac5fafe9f3","design_version_id":"5558253d-e704-5e89-b7dd-7eedee391e58","subsystem_id":"a842ebb8-c61c-5f2a-ba6c-163e9eb91000","rationale":"按源分配表及用户确认名称导入"}],"security_audit_events":[{"id":"a7e45661-411f-568b-bb89-f767d9de8c56","project_id":"10d4c8a0-ff3a-56c3-abf6-18dc3b531e62","actor_id":"__IMPORT_USER__","event_type":"sample.import","scope_kind":"project","after_state":{"source_checksum":"72407a7b3aca78e928865b654233ff4781668ff9e298b4ceb8bc9382bce353ef","counts":{"artifact_types":4,"artifact_type_versions":4,"projects":1,"business_functions":1,"project_members":1,"access_roles":1,"permission_definitions":7,"role_permissions":7,"access_bindings":1,"project_subsystem_designs":1,"subsystem_design_versions":1,"subsystems":43,"subsystem_version_items":43,"artifacts":32,"artifact_revisions":32,"prds":1,"prd_versions":1,"use_cases":3,"uc_versions":3,"uc_scenario_items":23,"functional_requirements":14,"fr_versions":14,"fr_uc_sources":16,"fr_allocations":14,"allocation_versions":14,"allocation_targets":14}},"reason":"操作人执行受控样本导入；原始文件不变","request_id":"xray:72407a7b3aca78e928865b654233ff4781668ff9e298b4ceb8bc9382bce353ef"}]}}'::jsonb; spec jsonb:='{"projects": {"pk": ["id"]}, "business_functions": {"pk": ["id"]}, "app_users": {"pk": ["id"]}, "project_members": {"pk": ["project_id", "user_id"]}, "artifact_types": {"pk": ["code"]}, "artifact_type_versions": {"pk": ["id"]}, "artifacts": {"pk": ["id"]}, "artifact_revisions": {"pk": ["id"]}, "prds": {"pk": ["artifact_id"]}, "prd_versions": {"pk": ["revision_id"]}, "use_cases": {"pk": ["artifact_id"]}, "uc_versions": {"pk": ["revision_id"]}, "uc_scenario_items": {"pk": ["uc_revision_id", "item_id"]}, "functional_requirements": {"pk": ["artifact_id"]}, "fr_versions": {"pk": ["revision_id"]}, "fr_uc_sources": {"pk": ["fr_revision_id", "uc_id"]}, "project_subsystem_designs": {"pk": ["project_id"]}, "subsystem_design_versions": {"pk": ["id"]}, "subsystems": {"pk": ["id"]}, "subsystem_version_items": {"pk": ["project_id", "design_version_id", "subsystem_id"]}, "fr_allocations": {"pk": ["artifact_id"]}, "allocation_versions": {"pk": ["revision_id"]}, "allocation_targets": {"pk": ["allocation_revision_id", "subsystem_id"]}, "permission_definitions": {"pk": ["code"]}, "access_roles": {"pk": ["id"]}, "role_permissions": {"pk": ["role_id", "permission_code"]}, "access_bindings": {"pk": ["id"]}, "security_audit_events": {"pk": ["id"]}, "review_events": {"pk": ["id"]}}'::jsonb; actor uuid; tab text; r jsonb; actual jsonb; pk_join text; k text; actual_count bigint;
BEGIN
 SELECT id INTO actor FROM ee.app_users WHERE external_subject=current_setting('ee.import_subject') AND state='active';
 IF actor IS NULL THEN RAISE EXCEPTION 'Expected real importer identity not found'; END IF;
 FOR tab IN SELECT jsonb_object_keys(payload->'data') LOOP
  IF payload->'data'->tab->0 ? 'project_id' THEN
   EXECUTE format('SELECT count(*) FROM ee.%I WHERE project_id=$1',tab) INTO actual_count USING (payload->>'project_id')::uuid;
   IF actual_count<>jsonb_array_length(payload->'data'->tab) THEN RAISE EXCEPTION 'Unexpected sample row count in %',tab; END IF;
  END IF;
  SELECT string_agg(format('t.%I = r.%I',value,value),' AND ') INTO pk_join FROM jsonb_array_elements_text(spec->tab->'pk');
  FOR r IN SELECT value FROM jsonb_array_elements(payload->'data'->tab) LOOP
   r=replace(r::text,'"__IMPORT_USER__"',to_jsonb(actor)::text)::jsonb;
   EXECUTE format('SELECT to_jsonb(t) FROM ee.%I t JOIN jsonb_populate_record(NULL::ee.%I,$1) r ON %s',tab,tab,pk_join) INTO actual USING r;
   IF actual IS NULL THEN RAISE EXCEPTION 'Missing expected row in %',tab; END IF;
   FOR k IN SELECT jsonb_object_keys(r) LOOP
    IF actual->k IS DISTINCT FROM r->k THEN RAISE EXCEPTION 'Content mismatch %.%',tab,k; END IF;
   END LOOP;
  END LOOP;
 END LOOP;
 IF EXISTS (SELECT 1 FROM ee.artifacts WHERE project_id='10d4c8a0-ff3a-56c3-abf6-18dc3b531e62'::uuid AND accepted_revision_id IS NOT NULL) THEN RAISE EXCEPTION 'Imported sample unexpectedly accepted'; END IF;
 IF EXISTS (SELECT 1 FROM ee.review_events WHERE project_id='10d4c8a0-ff3a-56c3-abf6-18dc3b531e62'::uuid) THEN RAISE EXCEPTION 'Unexpected review history'; END IF;
 IF EXISTS (SELECT 1 FROM ee.allocation_targets a LEFT JOIN ee.subsystem_version_items s USING(project_id,design_version_id,subsystem_id) WHERE a.project_id='10d4c8a0-ff3a-56c3-abf6-18dc3b531e62'::uuid AND (s.subsystem_id IS NULL OR NOT s.is_allocatable)) THEN RAISE EXCEPTION 'Invalid target'; END IF;
 RAISE NOTICE 'All expected source fields, numbered text, mappings and identities match; no fabricated acceptance.';
END $verify$;
SELECT type_code,count(*) AS sample_objects FROM ee.artifacts WHERE project_id='10d4c8a0-ff3a-56c3-abf6-18dc3b531e62'::uuid GROUP BY type_code ORDER BY type_code;
SELECT s.domain_group,s.name,count(t.subsystem_id) AS allocated_fr_count FROM ee.subsystem_version_items s LEFT JOIN ee.allocation_targets t USING(project_id,design_version_id,subsystem_id) WHERE s.project_id='10d4c8a0-ff3a-56c3-abf6-18dc3b531e62'::uuid GROUP BY s.domain_group,s.name,s.sort_order ORDER BY s.sort_order;
